ALTER TABLE public.universities ADD COLUMN IF NOT EXISTS initial_tuition_deposit_percentage NUMERIC(5,2) CHECK (initial_tuition_deposit_percentage BETWEEN 0 AND 100);

ALTER TABLE public.universities ADD COLUMN IF NOT EXISTS financial_terms_last_verified_at TIMESTAMPTZ;



DO $$ BEGIN IF EXISTS (SELECT 1 FROM public.universities WHERE regexp_replace(lower(name),'[^a-z0-9]+','','g') = ANY (ARRAY['universityofchester','chesteruniversity']) AND slug <> 'university-of-chester') THEN RAISE EXCEPTION 'Potential duplicate institution found before inserting University of Chester'; END IF; END $$;

