  initial_tuition_deposit_amount, initial_tuition_deposit_currency,
  initial_tuition_deposit_percentage, financial_terms_last_verified_at,
  submission_config_json
) VALUES (
  '3be6c6af-8f3a-4bca-8e06-1822094f7aef', (SELECT id FROM public.tenants WHERE slug='university-of-chester'), 'University of Chester', 'university-of-chester', 'Chester', 'United Kingdom', 'https://www.chester.ac.uk/', 'The University of Chester offers more than 200 courses across foundation, undergraduate, postgraduate taught and research study, with its main Chester sites supported by specialist locations in Warrington and Birkenhead.', true,
  'listed', 'unverified', 'none', 'https://www.chester.ac.uk/international/', 'official_public_source', '2026-08-24T00:00:00Z', '2026/27', '2026/27', 'profile_incomplete',
  'needs_review', 4, 4, 4, 0, 'needs_review',
  true, 10, 'The University of Chester offers more than 200 courses across foundation, undergraduate, postgraduate taught and research study, with its main Chester sites supported by specialist locations in Warrington and Birkenhead.', 'Official information checked 2026-08-24; confirm programme-specific conditions before applying',
  0, 'GBP', true,
  8000, 'GBP', NULL, '2026-08-24T00:00:00Z', '{"tagline":"Career-focused study in the historic city of Chester","highlights":["More than 200 courses advertised to international applicants","Foundation, undergraduate, postgraduate and research routes","Exton Park, Queen''s Park and specialist teaching locations","Dedicated international admissions and student experience support"],"internationalStudents":"International applicants receive country-specific admissions guidance, visa and CAS support, arrival information and help from the Student Experience team. Course availability, academic entry requirements and English requirements must be checked for the chosen programme.","tuition":"Published 2026/27 international fees are £11,250 for the foundation year of a bachelor''s degree, £14,950 per year for standard undergraduate study, £15,500 for standard postgraduate taught study, £15,700 for the MBA, £15,627 for classroom PhD study and £19,822 for laboratory PhD study. Medicine and some professional courses have different fees.","deposit":"The published international student checklist requires a minimum £8,000 enrolment-fee payment at least five working days before the course start date and before travel. Offer-specific and course-specific deadlines apply.","applicationFee":"Free direct application for foundation, undergraduate, postgraduate taught and MBA study; research applicants use the separate research application route.","scholarships":"Eligible undergraduate and 12-month postgraduate taught applicants are automatically considered for the University of Chester International Scholarship Award. The university does not publish one universal award value; the award shown in the offer letter controls.","entryRequirements":"Academic requirements are course and country specific. For Nigeria, the university publishes WAEC/SSCE routes for foundation study, recognised diploma or HND routes for undergraduate entry, and a recognised bachelor''s degree normally at 2:2/50%/GPA 2.4 or above for postgraduate study.","englishRequirements":"Requirements vary by course. The general international table starts at IELTS Academic 6.0 with minimum component scores for many taught courses. The Nigeria page confirms WAEC or NECO English at C/C6 or above for undergraduate study and C6 or above for postgraduate study; course exceptions apply.","accommodation":"University and partnership accommodation is available in and around Chester. Published 2026 options include catered and self-catered rooms, with first-year firm-choice applicants prioritised subject to the application deadline and availability.","studyLevels":["Foundation","Undergraduate","Postgraduate Taught","Postgraduate Research"],"applicationRouting":"guidance_only","locations":[{"city":"Chester","campus":"Exton Park","address":"Parkgate Road, Chester, CH1 4BJ"},{"city":"Chester","campus":"Queen''s Park"},{"city":"Warrington","campus":"University Centre Warrington"},{"city":"Birkenhead","campus":"University Centre Birkenhead"}],"sources":[{"url":"https://www.chester.ac.uk/international/","label":"Official international overview","checkedAt":"2026-08-24"},{"url":"https://www.chester.ac.uk/international/fees-scholarships-and-finance/fees/","label":"Official 2026/27 international fees","checkedAt":"2026-08-24"},{"url":"https://www.chester.ac.uk/international/fees-scholarships-and-finance/scholarships/","label":"Official international scholarships","checkedAt":"2026-08-24"},{"url":"https://www.chester.ac.uk/international/how-to-apply/making-an-application/","label":"Official application route and fee waiver","checkedAt":"2026-08-24"},{"url":"https://www.chester.ac.uk/international/how-to-apply/entry-requirements/","label":"Official English and academic requirements","checkedAt":"2026-08-24"},{"url":"https://www.chester.ac.uk/international/countries/nigeria/","label":"Official Nigeria requirements including WAEC and NECO","checkedAt":"2026-08-24"},{"url":"https://www.chester.ac.uk/welcome/before-you-arrive/international-student-checklist/","label":"Official enrolment payment guidance","checkedAt":"2026-08-24"},{"url":"https://www.chester.ac.uk/student-life/accommodation/","label":"Official accommodation information","checkedAt":"2026-08-24"}],"contacts":{},"social":{"website":"https://www.chester.ac.uk/"},"media":{}}'::jsonb
) ON CONFLICT (slug) DO UPDATE SET city=EXCLUDED.city, country=EXCLUDED.country, website=EXCLUDED.website, description=EXCLUDED.description, active=true, source_url=EXCLUDED.source_url, source_type=EXCLUDED.source_type, last_source_checked_at=EXCLUDED.last_source_checked_at, academic_year=EXCLUDED.academic_year, fee_year=EXCLUDED.fee_year, catalogue_status=EXCLUDED.catalogue_status, catalogue_discovered_count=EXCLUDED.catalogue_discovered_count, catalogue_processed_count=EXCLUDED.catalogue_processed_count, catalogue_verified_count=EXCLUDED.catalogue_verified_count, catalogue_unresolved_count=EXCLUDED.catalogue_unresolved_count, profile_readiness_status=EXCLUDED.profile_readiness_status, featured=true, featured_priority=EXCLUDED.featured_priority, featured_summary=EXCLUDED.featured_summary, featured_highlight=EXCLUDED.featured_highlight, application_fee_amount=EXCLUDED.application_fee_amount, application_fee_currency=EXCLUDED.application_fee_currency, application_fee_waived=EXCLUDED.application_fee_waived, initial_tuition_deposit_amount=EXCLUDED.initial_tuition_deposit_amount, initial_tuition_deposit_currency=EXCLUDED.initial_tuition_deposit_currency, initial_tuition_deposit_percentage=EXCLUDED.initial_tuition_deposit_percentage, financial_terms_last_verified_at=EXCLUDED.financial_terms_last_verified_at, submission_config_json=EXCLUDED.submission_config_json, updated_at=now();

