SELECT tenant_id,id,'University of Chester International Scholarship Award','University of Chester International Scholarship Award','university-of-chester-university-of-chester-international-scholarship-award','Eligible undergraduate and 12-month postgraduate taught applicants are automatically considered for the University of Chester International Scholarship Award. The university does not publish one universal award value; the award shown in the offer letter controls.',NULL,'GBP','partial','{"programmeAndApplicantConditionsApply":true}'::jsonb,false,true,'2026/27','United Kingdom','University of Chester','Award value is determined during application review and stated in the offer letter',true,false,'https://www.chester.ac.uk/international/fees-scholarships-and-finance/scholarships/','https://www.chester.ac.uk/international/fees-scholarships-and-finance/scholarships/','Eligible undergraduate and 12-month postgraduate taught applicants are automatically considered for the University of Chester International Scholarship Award. The university does not publish one universal award value; the award shown in the offer letter controls.','Eligibility and award value must be confirmed against the current official terms and the applicant offer.', 'Published','Fully Verified','2026-08-24T00:00:00Z',now() FROM public.universities WHERE slug='university-of-chester'
