INSERT INTO public.tenants (id, name, slug, email_from) VALUES ('2ff6d2b3-a2e5-4690-8d0d-716f65e3f21e', 'Wrexham University', 'wrexham-university', 'info@unidoxia.com') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.universities (
  id, tenant_id, name, slug, city, country, website, description, active,
  listing_status, verification_status, partnership_tier, source_url, source_type,
  last_source_checked_at, academic_year, fee_year, outreach_status,
  catalogue_status, catalogue_discovered_count, catalogue_processed_count,
  catalogue_verified_count, catalogue_unresolved_count, profile_readiness_status,
  featured, featured_priority, featured_summary, featured_highlight,
  application_fee_amount, application_fee_currency, application_fee_waived,
  initial_tuition_deposit_amount, initial_tuition_deposit_currency,
  initial_tuition_deposit_percentage, financial_terms_last_verified_at,
  submission_config_json
) VALUES (
  '8c9e7946-b9b3-469d-8c4e-879d151d2267', (SELECT id FROM public.tenants WHERE slug='wrexham-university'), 'Wrexham University', 'wrexham-university', 'Wrexham', 'United Kingdom', 'https://wrexham.ac.uk/', 'Wrexham University is a career-focused university in north-east Wales offering foundation, undergraduate, postgraduate and research routes, with practical learning and a compact campus close to Wrexham city centre and railway station.', true,
  'listed', 'unverified', 'none', 'https://wrexham.ac.uk/international-students/', 'official_public_source', '2026-08-24T00:00:00Z', '2026/27', '2026/27', 'profile_incomplete',
  'needs_review', 4, 4, 4, 0, 'needs_review',
  true, 11, 'Wrexham University is a career-focused university in north-east Wales offering foundation, undergraduate, postgraduate and research routes, with practical learning and a compact campus close to Wrexham city centre and railway station.', 'Official information checked 2026-08-24; confirm programme-specific conditions before applying',
  0, 'GBP', true,
  NULL, 'GBP', NULL, '2026-08-24T00:00:00Z', '{"tagline":"Career-focused and supportive study in north-east Wales","highlights":["Career-focused international course portfolio","Foundation, undergraduate, postgraduate and research study","On-campus en-suite accommodation close to the city centre","Published WAEC and NECO English alternatives"],"internationalStudents":"The international team provides admissions, visa, CAS and arrival guidance. Applicants should use the international course and intake finder because not every university course is necessarily available to international students in every intake.","tuition":"Published 2026/27 international fees are £11,750 per year for undergraduate study, £12,500 for MA/MSc courses, £13,000 for the MBA and £16,000 for PhD study. Intensive pathways and professional doctorates are not assigned a value where the official page says TBC.","deposit":"The CAS policy states that the minimum deposit required before CAS is the amount shown on the applicant''s unconditional offer letter. No single university-wide amount is published on the current international fees page.","applicationFee":"Wrexham University states that neither it nor its agents charge an application fee for any programme.","scholarships":"International undergraduate and postgraduate scholarships are advertised, but the current public international fees page does not publish one universal award value. Accommodation offers for 2026/27 separately advertise a limited 5% international accommodation discount for eligible non-NHS students, subject to availability and conditions.","entryRequirements":"Academic entry requirements are country and programme specific and must be checked through the official country pages and course page. Some programmes require portfolios, interviews, professional evidence or subject prerequisites.","englishRequirements":"The general undergraduate and postgraduate taught requirement is IELTS Academic 6.0 with no skill below 5.5; postgraduate research is IELTS 6.5 with no skill below 6.0. Accepted alternatives include LanguageCert, PTE, TOEFL, Cambridge, Trinity and country qualifications. WAEC English is accepted at C6 for taught study and C5 for research; NECO English is accepted at C6, subject to the published validity and individual assessment rules.","accommodation":"Wrexham Student Village offers furnished en-suite rooms on campus with bills, Wi-Fi and 24/7 security included. Published 2026/27 prices start at £132.50 per week for a standard single en-suite; availability and contract terms apply.","studyLevels":["Foundation","Undergraduate","Postgraduate Taught","Postgraduate Research"],"applicationRouting":"guidance_only","locations":[{"city":"Wrexham","campus":"Wrexham Campus","address":"Mold Road, Wrexham, LL11 2AW"}],"sources":[{"url":"https://wrexham.ac.uk/international-students/","label":"Official international overview","checkedAt":"2026-08-24"},{"url":"https://wrexham.ac.uk/courses/international-courses/","label":"Official international courses and intakes","checkedAt":"2026-08-24"},{"url":"https://wrexham.ac.uk/international-students/international-fees/","label":"Official 2026/27 international fees","checkedAt":"2026-08-24"},{"url":"https://wrexham.ac.uk/international-students/how-to-apply/","label":"Official application and no-fee statement","checkedAt":"2026-08-24"},{"url":"https://wrexham.ac.uk/international-students/english-language-requirements/","label":"Official English requirements including WAEC and NECO","checkedAt":"2026-08-24"},{"url":"https://wrexham.ac.uk/accommodation/student-accommodation/","label":"Official 2026/27 accommodation","checkedAt":"2026-08-24"},{"url":"https://wrexham.ac.uk/accommodation/accommodation-offers/","label":"Official 2026/27 international accommodation offer","checkedAt":"2026-08-24"}],"contacts":{},"social":{"website":"https://wrexham.ac.uk/"},"media":{}}'::jsonb
) ON CONFLICT (slug) DO UPDATE SET city=EXCLUDED.city, country=EXCLUDED.country, website=EXCLUDED.website, description=EXCLUDED.description, active=true, source_url=EXCLUDED.source_url, source_type=EXCLUDED.source_type, last_source_checked_at=EXCLUDED.last_source_checked_at, academic_year=EXCLUDED.academic_year, fee_year=EXCLUDED.fee_year, catalogue_status=EXCLUDED.catalogue_status, catalogue_discovered_count=EXCLUDED.catalogue_discovered_count, catalogue_processed_count=EXCLUDED.catalogue_processed_count, catalogue_verified_count=EXCLUDED.catalogue_verified_count, catalogue_unresolved_count=EXCLUDED.catalogue_unresolved_count, profile_readiness_status=EXCLUDED.profile_readiness_status, featured=true, featured_priority=EXCLUDED.featured_priority, featured_summary=EXCLUDED.featured_summary, featured_highlight=EXCLUDED.featured_highlight, application_fee_amount=EXCLUDED.application_fee_amount, application_fee_currency=EXCLUDED.application_fee_currency, application_fee_waived=EXCLUDED.application_fee_waived, initial_tuition_deposit_amount=EXCLUDED.initial_tuition_deposit_amount, initial_tuition_deposit_currency=EXCLUDED.initial_tuition_deposit_currency, initial_tuition_deposit_percentage=EXCLUDED.initial_tuition_deposit_percentage, financial_terms_last_verified_at=EXCLUDED.financial_terms_last_verified_at, submission_config_json=EXCLUDED.submission_config_json, updated_at=now();

