INSERT INTO public.tenants (id, name, slug, email_from) VALUES ('bd8e7dbb-c2d0-4129-8775-fb3056a368f8', 'York St John University', 'york-st-john-university', 'info@unidoxia.com') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.universities (
  id, tenant_id, name, slug, city, country, website, description, active,
  listing_status, verification_status, partnership_tier, source_url, source_type,
  last_source_checked_at, academic_year, fee_year, outreach_status,
  catalogue_status, catalogue_discovered_count, catalogue_processed_count,
  catalogue_verified_count, catalogue_unresolved_count, profile_readiness_status,
  featured, featured_priority, featured_summary, featured_highlight,
  application_fee_amount, application_fee_currency, application_fee_waived,
  initial_tuition_deposit_amount, initial_tuition_deposit_currency,
  initial_tuition_deposit_percentage, financial_terms_last_verified_at,
  submission_config_json
) VALUES (
  '51e22435-005a-44fd-8cc7-4ad68ad719bd', (SELECT id FROM public.tenants WHERE slug='york-st-john-university'), 'York St John University', 'york-st-john-university', 'York', 'United Kingdom', 'https://www.yorksj.ac.uk/', 'York St John University offers undergraduate, postgraduate and research study from its city-centre York campus, with additional provision in London, and emphasises practical learning, community and lifelong careers support.', true,
  'listed', 'unverified', 'none', 'https://www.yorksj.ac.uk/international/', 'official_public_source', '2026-08-24T00:00:00Z', '2026/27', '2026/27', 'profile_incomplete',
  'needs_review', 4, 4, 4, 1, 'needs_review',
  true, 12, 'York St John University offers undergraduate, postgraduate and research study from its city-centre York campus, with additional provision in London, and emphasises practical learning, community and lifelong careers support.', 'Official information checked 2026-08-24; confirm programme-specific conditions before applying',
  NULL, 'GBP', NULL,
  NULL, 'GBP', 50, '2026-08-24T00:00:00Z', '{"tagline":"Supportive, career-connected study in the centre of York","highlights":["City-centre York campus","Foundation, undergraduate, postgraduate and doctoral routes","Placement and professional-experience options on selected courses","Careers support available to graduates for life"],"internationalStudents":"International applicants can apply directly or through UCAS and receive country guidance, visa and CAS support. Applicants must confirm the teaching campus because York and London provision, fees and course availability can differ.","tuition":"Fees are programme specific. Verified examples for 2026/27 include £12,100 per year for Computer Science BSc, £14,900 per year for Law LLB, £11,800 for the standard one-year International Business MSc, £15,400 for its professional-experience route and £14,900 per year for full-time PhD study.","deposit":"Student-visa applicants normally pay 50% of the first year''s tuition fee after an unconditional offer. For a two-year MBA or MSc with professional experience, the required deposit is 50% of the total course fee. Exemptions apply to specified sponsored and loan-funded students.","applicationFee":"The official direct-application page does not publish a university application fee. UniDoxia therefore records the application fee as unconfirmed rather than asserting that it is waived.","scholarships":"A £1,000 scholarship is published for eligible international fee-paying undergraduates enrolling on any undergraduate course at the York campus. Separate funding and research opportunities have their own conditions.","entryRequirements":"Requirements are course and country specific. Standard undergraduate pages publish UCAS tariff and GCSE-equivalent requirements; many taught postgraduate programmes require a 2:2 honours degree or equivalent, sometimes with relevant experience. Research applicants must identify a suitable supervisor and meet project-specific requirements.","englishRequirements":"For many courses the September 2026 standard is IELTS Academic 6.0 with no component below 5.5, with accepted alternatives including Cambridge, Duolingo, PTE, LanguageCert, Trinity, TOEFL and Oxford Test of English. MRes, PhD and regulated courses publish higher or different scores. The reviewed official pages did not clearly confirm WAEC or NECO as an English waiver, so UniDoxia does not claim one.","accommodation":"First-year undergraduate applicants can access university-managed or partner accommodation subject to published deadlines. Main sites have 24-hour security support and rent includes bills, Wi-Fi and contents insurance; a £200 advance payment is applied to the first instalment.","studyLevels":["Foundation","Undergraduate","Postgraduate Taught","Postgraduate Research"],"applicationRouting":"guidance_only","locations":[{"city":"York","campus":"York Campus","address":"Lord Mayor''s Walk, York, YO31 7EX"},{"city":"London","campus":"London Campus","address":"6th Floor, Export Building, 1 Clove Crescent, London, E14 2BA"}],"sources":[{"url":"https://www.yorksj.ac.uk/international/","label":"Official international overview","checkedAt":"2026-08-24"},{"url":"https://www.yorksj.ac.uk/international/how-to-apply/apply-direct/","label":"Official direct application and 2026 deadlines","checkedAt":"2026-08-24"},{"url":"https://www.yorksj.ac.uk/international/how-to-apply/english-language-requirements/","label":"Official September 2026 English requirements","checkedAt":"2026-08-24"},{"url":"https://www.yorksj.ac.uk/international/funding-scholarships-and-paying-tuition-fees/","label":"Official international funding and £1,000 scholarship","checkedAt":"2026-08-24"},{"url":"https://www.yorksj.ac.uk/international/international-offer-holders/preparing-for-cas/","label":"Official 50% deposit requirement","checkedAt":"2026-08-24"},{"url":"https://www.yorksj.ac.uk/policies-and-documents/accommodation/","label":"Official 2026/27 accommodation information","checkedAt":"2026-08-24"}],"contacts":{},"social":{"website":"https://www.yorksj.ac.uk/"},"media":{}}'::jsonb
) ON CONFLICT (slug) DO UPDATE SET city=EXCLUDED.city, country=EXCLUDED.country, website=EXCLUDED.website, description=EXCLUDED.description, active=true, source_url=EXCLUDED.source_url, source_type=EXCLUDED.source_type, last_source_checked_at=EXCLUDED.last_source_checked_at, academic_year=EXCLUDED.academic_year, fee_year=EXCLUDED.fee_year, catalogue_status=EXCLUDED.catalogue_status, catalogue_discovered_count=EXCLUDED.catalogue_discovered_count, catalogue_processed_count=EXCLUDED.catalogue_processed_count, catalogue_verified_count=EXCLUDED.catalogue_verified_count, catalogue_unresolved_count=EXCLUDED.catalogue_unresolved_count, profile_readiness_status=EXCLUDED.profile_readiness_status, featured=true, featured_priority=EXCLUDED.featured_priority, featured_summary=EXCLUDED.featured_summary, featured_highlight=EXCLUDED.featured_highlight, application_fee_amount=EXCLUDED.application_fee_amount, application_fee_currency=EXCLUDED.application_fee_currency, application_fee_waived=EXCLUDED.application_fee_waived, initial_tuition_deposit_amount=EXCLUDED.initial_tuition_deposit_amount, initial_tuition_deposit_currency=EXCLUDED.initial_tuition_deposit_currency, initial_tuition_deposit_percentage=EXCLUDED.initial_tuition_deposit_percentage, financial_terms_last_verified_at=EXCLUDED.financial_terms_last_verified_at, submission_config_json=EXCLUDED.submission_config_json, updated_at=now();

